import minecraft_launcher_lib as mc
import subprocess
import base64
import tkinter as tk

off_data = '''


'''

on_data = '''


'''

image_data_light = '''

'''

image_data_dark = '''


'''


app = tk.Tk()
app.title("Lectern")
app.title("Lectern Minecraft Launcher")
username = tk.StringVar(value="")
uuid = tk.StringVar(value="")
token = tk.StringVar(value="")
Username = tk.Label(app, text="Username, pick any username but dont leave me empty! You can steal skins...")
Username_enter = tk.Entry(app, textvariable=username)
UUID = tk.Label(app, text="UUID, get one from: https://www.uuidgenerator.net/  dont leave me empty!")
UUID_enter = tk.Entry(app, textvariable=uuid)
on = tk.PhotoImage(data=base64.b64decode(on_data))
off = tk.PhotoImage(data=base64.b64decode(off_data))
path = mc.utils.get_minecraft_directory()
Ver_select = drop_description = tk.Label(app, text="Select a version. If you leave it as is it will install and launch 1.19 (shipped with Lectern Launcher).")
version = tk.StringVar(app)
version.set("1.19")
Warning = tk.Label(text="To play using neoforge click install and then launch to launch it.")
version_menu = tk.OptionMenu(app, version, "1.19", "1.20", "1.21.2", "1.19", "1.18", "1.17", "1.16", "1.15", "1.14", "1.13", "1.12", "1.12.2", "1.11", "1.11.1", "1.10", "1.9", "1.8.8")
def install():
    mc.utils.get_installed_versions(path)
    mc.install.install_minecraft_version(version.get(), path)
    print("Minecraft version is installed at"+" "+path)

def launch():
    configuration = {
        "username": username.get(),
        "uuid": uuid.get(),
        "token": "offline",
    }
    minecraft_command = mc.command.get_minecraft_command(version.get(), path, configuration)
    subprocess.call(minecraft_command)

def neoforge_install():
    loader = mc.mod_loader.get_mod_loader("neoforge")
    loader.install("1.21.2", path)
print("Minecraft is at or will be created at"+" "+path)

def neoforge_launch():
    configuration = {
        "username": username.get(),
        "uuid": uuid.get(),
        "token": "offline",
    }
    minecraft_command = mc.command.get_minecraft_command("neoforge-21.2.1-beta", path, configuration)
    subprocess.call(minecraft_command)

Install = tk.Button(app, text="Install", command=install)
Launch = tk.Button(app, text="Launch", command=launch)
Install_neo = tk.Button(text="Install neoforge (21.2.1)", command=neoforge_install)
Launch_neo = tk.Button(text="Launch neoforge (21.2.1)", command=neoforge_launch)
Icon_light = tk.PhotoImage(data=base64.b64decode(image_data_light))
Icon_dark = tk.PhotoImage(data=base64.b64decode(image_data_dark))
toggle_mode = True
def toggle_custom():
    global toggle_mode
    if toggle_mode:
        toggle.config(image=off, bg="#353535", activebackground="#353535", bd=0, highlightthickness=0)
        app.config(bg="#353535")
        Username.config(bg="#353535", activebackground="#353535", fg="white")
        Username_enter.config(bg="#353535", fg="white")
        UUID.config(bg="#353535", activebackground="#353535", fg="white")
        UUID_enter.config(bg="#353535", fg="white")
        version_menu.config(bg="#353535", activebackground="#353535")
        Warning.config(bg="#353535", activebackground="#353535", fg="white")
        Install.config(bg="#353535", activebackground="#353535")
        Launch.config(bg="#353535", activebackground="#353535")
        Install_neo.config(bg="#353535", activebackground="#353535")
        Launch_neo.config(bg="#353535", activebackground="#353535")
        label.config(bg="#353535", image=Icon_dark)
        toggle_mode = False
    else:
        toggle.config(image=on, bg="white", activebackground="white", bd=0, highlightthickness=0)
        app.config(bg="white")
        Username.config(bg="white", activebackground="white", fg=("black"))
        Username_enter.config(bg="white", fg=("black"))
        UUID.config(bg="white", activebackground="white", fg=("black"))
        UUID_enter.config(bg="white", fg=("black"))
        version_menu.config(bg="white", activebackground="white", fg=("black"))
        Warning.config(bg="white", activebackground="white", fg=("black"))
        Install.config(bg="white", activebackground="white")
        Launch.config(bg="white", activebackground="white")
        Install_neo.config(bg="white", activebackground="white")
        Launch_neo.config(bg="white", activebackground="white")
        label.config(bg="white", image=Icon_light)
        toggle_mode = True

toggle = tk.Button(app, image=on, bd=0, highlightthickness=0, bg="white", activebackground="white",command=toggle_custom)
app.config(bg="white")
toggle.pack()
label = tk.Label(app, image=Icon_light, bd=0, highlightthickness=0)
label.pack()
Username.pack()
Username_enter.pack()
UUID.pack()
UUID_enter.pack()
Warning.pack()
version_menu.pack()
Install.pack()
Launch.pack()
Install_neo.pack()
Launch_neo.pack()
app.mainloop()
